/// this file handles reading the file generated by cpu-speeds.rs
use std::collections::HashMap;

use crate::errors::*;

pub const REFERENCE_CPU_MODEL: &str = "Intel Core i7-8700K CPU @ 3.70GHz";
pub const REFERENCE_CPU_SPEED: u32 = 1000;

// fix some minor variations that happen depending on... OS, or something
pub fn normalize_cpu_model(cpu_model: &str) -> String {
    let mut cpu_model = cpu_model.to_owned();
    for mark in ["(R)", "(TM)", "(tm)"] {
        cpu_model = cpu_model.replace(mark, "");
    }
    cpu_model.split_whitespace().collect::<Vec<_>>().join(" ")
}

// also see: format_cpu_speed_table() in cpu-speeds.rs
pub fn parse_cpu_speed_table(table: &str) -> Result<HashMap<String, u32>> {
    let mut speeds = HashMap::new();
    for (index, line) in table.lines().enumerate() {
        if line.starts_with('#') {
            continue;
        }
        let line_number = index + 1;
        let (speed, cpu_model) = line
            .split_once('\t')
            .with_context(|| format!("Line {line_number} has no tab"))?;
        let speed: u32 = speed
            .parse()
            .with_context(|| format!("Line {line_number} has an invalid speed {speed:?}"))?;
        if speed == 0 {
            bail!("Line {line_number} has speed 0")
        }
        if normalize_cpu_model(cpu_model) != cpu_model {
            bail!("Line {line_number} has a CPU model that is not normalized: {cpu_model:?}")
        }
        if speeds.insert(cpu_model.to_owned(), speed).is_some() {
            bail!("Line {line_number} repeats the CPU model {cpu_model:?}")
        }
    }
    if speeds.get(REFERENCE_CPU_MODEL) != Some(&REFERENCE_CPU_SPEED) {
        bail!("The table does not give {REFERENCE_CPU_MODEL} the speed {REFERENCE_CPU_SPEED}")
    }
    Ok(speeds)
}

#[cfg(test)]
mod test {
    use super::*;

    #[test]
    fn test_normalize_cpu_model() {
        assert_eq!(
            normalize_cpu_model("Intel(R) Core(TM) i7-8700K CPU @ 3.70GHz"),
            REFERENCE_CPU_MODEL
        );
        assert_eq!(
            normalize_cpu_model(REFERENCE_CPU_MODEL),
            REFERENCE_CPU_MODEL
        );
        assert_eq!(
            normalize_cpu_model("Intel(R) Xeon(R) CPU           X5690  @ 3.47GHz"),
            "Intel Xeon CPU X5690 @ 3.47GHz"
        );
        assert_eq!(
            normalize_cpu_model("  AMD Ryzen 9 5950X 16-Core Processor            "),
            "AMD Ryzen 9 5950X 16-Core Processor"
        );
        assert_eq!(
            normalize_cpu_model("AMD Athlon(tm) II X4 640 Processor"),
            "AMD Athlon II X4 640 Processor"
        );
        assert_eq!(
            normalize_cpu_model("INTEL XEON GOLD 6542Y (Skylake)"),
            "INTEL XEON GOLD 6542Y (Skylake)"
        );
        assert_eq!(normalize_cpu_model(" \t "), "");
    }

    #[test]
    fn test_valid_table() {
        let table = "# comment\n1000\tIntel Core i7-8700K CPU @ 3.70GHz\n1224\tAMD Ryzen 9 5950X 16-Core Processor\n";
        assert_eq!(
            parse_cpu_speed_table(table).unwrap(),
            HashMap::from([
                (REFERENCE_CPU_MODEL.to_owned(), REFERENCE_CPU_SPEED),
                ("AMD Ryzen 9 5950X 16-Core Processor".to_owned(), 1224),
            ])
        );
    }

    #[test]
    fn test_invalid_tables() {
        const REFERENCE: &str = "1000\tIntel Core i7-8700K CPU @ 3.70GHz\n";
        for invalid in [
            "1 AMD Ryzen 9 5950X 16-Core Processor\n",
            "fast\tAMD Ryzen 9 5950X 16-Core Processor\n",
            "-1\tAMD Ryzen 9 5950X 16-Core Processor\n",
            "0\tAMD Ryzen 9 5950X 16-Core Processor\n",
            "1\tAMD(tm) Ryzen 9 5950X 16-Core Processor\n",
            "1\tAMD Ryzen 9 5950X 16-Core Processor \n",
            "1\tAMD Ryzen 9 5950X 16-Core Processor\n2\tAMD Ryzen 9 5950X 16-Core Processor\n",
        ] {
            let table = format!("{REFERENCE}{invalid}");
            assert!(parse_cpu_speed_table(&table).is_err(), "{table:?}");
        }
        for without_reference in [
            "# only a comment\n",
            "1224\tAMD Ryzen 9 5950X 16-Core Processor\n",
            "999\tIntel Core i7-8700K CPU @ 3.70GHz\n",
        ] {
            assert!(
                parse_cpu_speed_table(without_reference).is_err(),
                "{without_reference:?}"
            );
        }
    }
}
